python3 << 'EOF'
import json, re, os

with open('apps/web/src/assets/i18n/en.json') as f:
    en = json.load(f)

def collect(d, p=''):
    r = {}
    for k, v in d.items():
        full = f'{p}.{k}' if p else k
        if isinstance(v, dict):
            r.update(collect(v, full))
        else:
            r[full] = v
    return r

en_flat = collect(en)
ph_re = re.compile(r'\{\{[^}]+\}\}')
en_phs = {k: sorted(ph_re.findall(v)) for k, v in en_flat.items() if ph_re.search(v)}
print(f'EN keys with placeholders: {len(en_phs)}')

issues = 0
for fn in sorted(os.listdir('apps/web/src/assets/i18n')):
    if not fn.endswith('.json') or fn == 'en.json':
        continue
    with open(f'apps/web/src/assets/i18n/{fn}') as f:
        d = json.load(f)
    flat = collect(d)
    bad = []
    for k, en_p in en_phs.items():
        if k not in flat:
            continue
        loc_p = sorted(ph_re.findall(flat[k]))
        if loc_p != en_p:
            bad.append((k, en_p, loc_p))
    if bad:
        issues += len(bad)
        print(f'\n{fn}: {len(bad)} placeholder mismatches')
        for k, ep, lp in bad[:5]:
            print(f'  {k}: en={ep} loc={lp}')
print(f'\nTotal placeholder issues: {issues}')
EOF

